using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;
namespace GearLab {
 public static class CompoundUiTests {public static int Run(string folder){Directory.CreateDirectory(folder);try{using(var form=new TrainDesignerForm(CompoundReducer.Example())){form.ShowInTaskbar=false;form.Opacity=0;form.Show();Application.DoEvents();form.CompoundVerify(folder);form.WorkspaceApproveClose();form.Close();}File.WriteAllText(Path.Combine(folder,"compound-ui-results.json"),"{\"Passed\":true}");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"compound-ui-error.txt"),ex.ToString());return 1;}}}
 public sealed partial class TrainDesignerForm {
  internal void CompoundVerify(string folder){Calculate();if(solution==null||!solution.Valid||solution.Compound==null)throw new Exception("Compound UI model missing");if(!commonHousing.Checked||housingProperties.SelectedObject!=document.SharedHousing)throw new Exception("Housing controls not bound");using(var bmp=new Bitmap(620,720))using(var schematic=new CompoundSectionPanel{Size=new Size(620,720),Solution=solution}){schematic.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(Path.Combine(folder,"compound-section.png"));}viewer.Scene.SetResult(null,false);viewer.Scene.SetResult(solution.Scene,false);viewer.Scene.Root.Measure(new System.Windows.Size(1000,800));viewer.Scene.Root.Arrange(new System.Windows.Rect(0,0,1000,800));viewer.Fit();if(!viewer.Scene.Ready||viewer.Scene.Nodes.Count!=solution.Scene.Model.Parts.Count)throw new Exception("3D scene incomplete: "+viewer.Scene.Error);viewer.Scene.SavePng(Path.Combine(folder,"compound-3d.png"),1000,800);viewer.SetExploded(true);viewer.Scene.SavePng(Path.Combine(folder,"compound-exploded.png"),1000,800);viewer.SetExploded(false);}
 }
}
